html, body, div, span, applet, object, iframe, h1, h2, h3, h4, h5, h6, p, blockquote, pre, a, abbr, acronym, address, big, cite, code, del, dfn, em, img, ins, kbd, q, s, samp, small, strike, strong, sub, sup, tt, var, b, u, i, center, dl, dt, dd, ol, ul, li, fieldset, form, input, label, legend, table, caption, tbody, tfoot, thead, tr, th, td, article, aside, canvas, details, embed, figure, figcaption, footer, header, hgroup, menu, nav, output, ruby, section, summary, time, mark, audio, video {
  border: 0;
  font-size: 100%;
  font: inherit;
  margin: 0;
  padding: 0;
  vertical-align: top;
}

article, aside, details, figcaption, figure, footer, header, hgroup, menu, nav, section {
  display: block;
}

body {
  line-height: 1;
}

ol, ul, menu {
  list-style: none;
}

blockquote, q {
  quotes: none;
}

blockquote:before, blockquote:after, q:before, q:after {
  content: "";
  content: none;
}

table {
  border-collapse: collapse;
  border-spacing: 0;
}

form, input, button {
  -webkit-appearance: none;
  -webkit-tap-highlight-color: transparent;
  background-color: transparent;
  border-radius: 0;
  border: none;
  margin: 0;
  padding: 0;
  text-align: left;
}
form:invalid, input:invalid, button:invalid {
  box-shadow: none;
}

input::-ms-clear {
  display: none;
}
input:-webkit-autofill, input:-webkit-autofill:active, input:-webkit-autofill:focus, input:-webkit-autofill:hover {
  transition-duration: 5000s;
  transition-property: background-color;
}

details summary::-webkit-details-marker {
  display: none;
}

button > * {
  position: relative;
}

html {
  font-size: 62.5%;
}
html, html * {
  -webkit-text-size-adjust: none;
}

* {
  box-sizing: border-box;
}

body {
  -moz-osx-font-smoothing: grayscale;
  -webkit-font-smoothing: antialiased;
  font-family: "MoMA Sans", Helvetica, sans-serif;
  font-kerning: normal;
  font-weight: 400;
  text-rendering: optimizeLegibility;
}

input::placeholder, button, form, input, :lang(ja), :lang(ko), :lang(zh-Hant), :lang(zh-Hans), body {
  font-family: "MoMA Sans", var(--language-font-face), Helvetica, sans-serif;
}

:root,
:lang(en) {
  --language-font-face: "MoMA Sans";
}

:lang(zh-Hans) {
  --language-font-face: "Noto Sans SC";
}

:lang(zh-Hant) {
  --language-font-face: "Noto Sans TC";
}

:lang(ko) {
  --language-font-face: "Noto Sans KR";
}

:lang(ja) {
  --language-font-face: "Noto Sans JP";
}

em, i {
  font-style: italic;
}
em em, em i, i em, i i {
  font-style: normal;
}
em em em, em em i, em i em, em i i, i em em, i em i, i i em, i i i {
  font-style: italic;
}

del {
  font-style: line-through;
}

a {
  color: inherit;
  text-decoration: none;
}

